<?php
require_once __DIR__ . '/_bootstrap.php';
$orders = (int) customerScalar("SELECT COUNT(*) FROM orders WHERE user_id = ?", [$customerId]);
$pending = (int) customerScalar("SELECT COUNT(*) FROM orders WHERE user_id = ? AND order_status IN ('pending','processing','confirmed')", [$customerId]);
$spent = (float) customerScalar("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE user_id = ? AND order_status NOT IN ('cancelled','failed')", [$customerId]);
$unread = (int) customerScalar("SELECT COUNT(*) FROM notifications WHERE user_id = ? AND is_read = 0", [$customerId]);
$recent = customerRows("SELECT id, order_number, total_amount, order_status, created_at FROM orders WHERE user_id = ? ORDER BY created_at DESC LIMIT 5", [$customerId]);
customerPageStart('Customer dashboard', 'Dashboard');
?><div class="cw-title"><div><h1>Welcome back, <?= e($customer['first_name'] ?? 'Customer') ?></h1><p>Your Alibaba-inspired Quincy Store workbench.</p></div><a class="cw-btn gold" href="<?= e(BASE_URL) ?>/shop/products.php">Continue shopping</a></div>
<section class="cw-grid cw-grid-4"><div class="cw-card cw-stat"><strong><?= $orders ?></strong><span>Total orders</span></div><div class="cw-card cw-stat"><strong><?= $pending ?></strong><span>In progress</span></div><div class="cw-card cw-stat"><strong><?= e(formatPrice($spent)) ?></strong><span>Total spend</span></div><div class="cw-card cw-stat"><strong><?= $unread ?></strong><span>Unread updates</span></div></section>
<div class="cw-grid cw-grid-2" style="margin-top:20px"><section class="cw-card"><div class="cw-title"><h2>Recent orders</h2><a href="orders.php">View all →</a></div><?php if(!$recent): ?><div class="cw-empty">No orders yet. Your first purchase will appear here.</div><?php else: ?><table class="cw-table"><tr><th>Order</th><th>Status</th><th>Total</th></tr><?php foreach($recent as $row): ?><tr><td><a href="order-details.php?id=<?= (int)$row['id'] ?>"><strong>#<?= e($row['order_number'] ?? $row['id']) ?></strong></a><br><span class="muted"><?= e(date('M j, Y',strtotime($row['created_at']))) ?></span></td><td><span class="badge"><?= e(ucfirst((string)$row['status'])) ?></span></td><td><?= e(formatPrice($row['total_amount'] ?? 0)) ?></td></tr><?php endforeach; ?></table><?php endif; ?></section>
<section class="cw-card"><h2>Quick actions</h2><p class="muted">Everything you need to manage your purchases.</p><div class="cw-actions"><a class="cw-btn alt" href="profile.php">Edit profile</a><a class="cw-btn alt" href="addresses.php">Manage addresses</a><a class="cw-btn alt" href="notifications.php">Notifications</a><a class="cw-btn alt" href="support.php">Get support</a></div></section></div><?php customerPageEnd(); ?>